INSERT INTO `scenario_step_locale` VALUES (16853,'deDE','Schreine werden für die Verwendung ermächtigt.','Die Schreine ermächtigen',69497),(16853,'esES','Los santuarios se están potenciando para su uso.','Potencia los santuarios',69497),(16853,'esMX','Se están potenciando los santuarios para usarse.','Potencia los santuarios',69497),(16853,'frFR','Les sanctuaires sont renforcés afin d’être utilisés.','Renforcement des sanctuaires',69497),(16853,'itIT','I santuari vengono potenziati per l\'uso.','Potenzia i Santuari',69497),(16853,'koKR','제단을 사용할 수 있도록 힘을 불어넣는 중입니다.','제단 강화',69497),(16853,'ptBR','Santuários estão sendo potencializados para o uso.','Potencialize os santuários',69497),(16853,'ruRU','Святилища насыщаются силой.','Усиление святилищ',69497),(16853,'zhCN','神龛正在被强化以供使用。','强化神龛',69497),(16853,'zhTW','聖壇受到強化，可供使用。','強化聖壇',69497),(16856,'deDE','Tötet Schlangen und stört Rituale, bevor sie den Tempel überrennen.','Die Flut der Schlangen eindämmen',69497),(16856,'esES','Asesina sierpes e interrumpe rituales antes de que invadan el templo.','Frena la marea de sierpes',69497),(16856,'esMX','Mata serpientes e interrumpe los rituales antes de que arrasen con el templo.','Detén la oleada de serpientes',69497),(16856,'frFR','Terrassez des serpents et interrompez les rituels avant qu’ils envahissent le temple.','Repousser la marée de serpents',69497),(16856,'itIT','Uccidi i serpenti e interrompi i rituali prima che invadano il tempio.','Argina l\'Ondata di Serpenti',69497),(16856,'koKR','사원을 장악하려고 드는 뱀들을 처치하고 의식을 방해해야 합니다.','뱀의 공세 저지',69497),(16856,'ptBR','Mate serpentes e desfaça rituais antes que elas infestem o templo.','Contenha a maré de serpentes',69497),(16856,'ruRU','Убейте змей и прервите ритуалы, чтобы уберечь храм.','Оборона от змей',69497),(16856,'zhCN','在蛇群淹没神殿之前将其消灭并破坏仪式。','击退蛇群狂潮',69497),(16856,'zhTW','殺死毒蛇並打斷儀式，防止神殿淪陷。','殲滅蛇潮',69497),(16858,'deDE','Nutzt die Schreine, um Unreinheitskugeln zu sammeln.','Die Schreine von Erde und Himmel nutzen',69497),(16858,'esES','Usa los santuarios para conseguir orbes de impureza.','Usa los Santuarios de Tierra y Cielo',69497),(16858,'esMX','Utiliza los santuarios para recolectar orbes de impureza.','Usa los santuarios de tierra y cielo',69497),(16858,'frFR','Utilisez les sanctuaires pour récupérer des orbes d’impureté.','Utiliser les sanctuaires de terre et du ciel',69497),(16858,'itIT','Usa i Santuari per raccogliere i Globi d\'Impurità.','Usa il Santuario della Terra e il Santuario del Cielo',69497),(16858,'koKR','제단을 사용해 불순물 보주를 모아야 합니다.','하늘과 대지의 제단 사용',69497),(16858,'ptBR','Utilize os santuários para coletar Orbes de Impureza.','Use os Santuários de Terra e de Céu',69497),(16858,'ruRU','Используйте святилища для сбора нечистых сфер.','Помощь святилищ неба и земли',69497),(16858,'zhCN','利用神龛收集不洁宝珠。','使用净化天地神龛',69497),(16858,'zhTW','利用聖壇收集不潔球體。','使用大地和天空聖壇',69497),(16873,'deDE','Sammelt boshafte Geister und verbrennt sie auf Geisterscheiterhaufen. Nehmt die Flammen von den Scheiterhaufen, um entweihte Sarkophage zu vernichten.','Läuterung der Untoten',69497),(16873,'esES','Reúne espíritus perversos y quémalos en piras espirituales. Lleva llamas a las piras para destruir los sarcófagos profanados.','Purga a los no-muertos',69497),(16873,'esMX','Reúne espíritus perversos y quémalos en las piras espirituales. Lleva las llamas de las piras y destruye los sarcófagos profanados.','Purga a los no-muertos',69497),(16873,'frFR','Rassemblez des esprits malfaisants et brûlez-les sur les bûchers spirituels. Transportez les flammes des bûchers pour détruire des sarcophages profanés.','Purge des morts-vivants',69497),(16873,'itIT','Raduna gli Spiriti Malevoli e bruciali alle Pire Spirituali. Trasporta le fiamme dalle pire per distruggere i Sarcofagi Profanati.','Epura i Non Morti',69497),(16873,'koKR','사악한 영혼을 모아 영혼 장작더미에서 불태워야 합니다. 장작더미의 불길을 가져가 더럽혀진 석관을 파괴해야 합니다.','언데드 정화',69497),(16873,'ptBR','Reúna Espíritos Malignos e queime-os em Piras Espirituais. Leve as chamas das piras para destruir Sarcófagos Profanados.','Expurgue os mortos-vivos',69497),(16873,'ruRU','Соберите зловещих духов и сожгите их на призрачных погребальных кострах. Донесите пламя костров до оскверненных саркофагов и подожгите их.','Избавление от нежити',69497),(16873,'zhCN','收集卑劣的精魂并在精魂火堆将其焚烧。将火堆中的烈焰带去摧毁被亵渎的石棺。','净化亡灵',69497),(16873,'zhTW','收集邪惡靈魂，然後在靈魂火堆燒掉靈魂。攜帶火堆的烈焰，摧毀被褻瀆的石棺。','淨化不死族',69497),(16875,'deDE','Bringt die drei Stäbe von jedem Stein zur Truhe.','Die Knüppel bergen',69497),(16875,'esES','Lleva los tres báculos de cada piedra al alijo.','Recupera los báculos',69497),(16875,'esMX','Lleva los tres bastones de cada piedra al Alijo.','Recupera los bastones',69497),(16875,'frFR','Transportez les trois cannes de chaque pierre à la cache.','Récupérer les cannes',69497),(16875,'itIT','Trasporta le tre verghe da ciascuna pietra alla cassa.','Recupera i Bastoni',69497),(16875,'koKR','각 돌에서 입수한 지팡이 3개를 보관함으로 가져가야 합니다.','지팡이 회수',69497),(16875,'ptBR','Leve os três cajados de cada rocha até o tesouro.','Recupere os cajados',69497),(16875,'ruRU','Отнесите в тайник три посоха от каждого камня.','Возвращение посохов',69497),(16875,'zhCN','将三根法杖从各块石头处带到宝箱。','取回法杖',69497),(16875,'zhTW','將三把護杖從每個岩石帶到儲物箱。','取回護杖',69497),(16876,'deDE','Truhe freigeschaltet.','Truhe freigeschaltet',69497),(16876,'esES','Alijo desbloqueado.','Alijo desbloqueado',69497),(16876,'esMX','Alijo desbloqueado.','Alijo desbloqueado',69497),(16876,'frFR','Cache débloquée.','Cache débloquée',69497),(16876,'itIT','Cassa sbloccata.','Cassa Sbloccata',69497),(16876,'koKR','보관함의 잠금을 해제해야 합니다.','보관함 잠금 해제',69497),(16876,'ptBR','Tesouro desbloqueado.','Tesouro desbloqueado',69497),(16876,'ruRU','Тайник открыт.','Открытие тайника',69497),(16876,'zhCN','宝箱已解锁。','宝箱已解锁',69497),(16876,'zhTW','解鎖儲物箱。','解鎖儲物箱',69497),(16918,'deDE','Wartet, dass sich das Portal öffnet.','Das Portal beschwören',69497),(16918,'esES','Espera a que se abra el portal.','Invoca el portal',69497),(16918,'esMX','Espera a que se abra el portal.','Invoca el portal',69497),(16918,'frFR','Attendez que le portail s’ouvre.','Invocation du portail',69497),(16918,'itIT','Aspetta che il portale si apra.','Evoca il Portale',69497),(16918,'koKR','차원문이 열릴 때까지 기다려야 합니다.','차원문 소환',69497),(16918,'ptBR','Aguarde a abertura do portal.','Evoque o Portal',69497),(16918,'ruRU','Дождитесь открытия портала.','Открытие портала',69497),(16918,'zhCN','等待传送门开启。','召唤传送门',69497),(16918,'zhTW','等待傳送門開啟。','召喚傳送門',69497),(16919,'deDE','Betretet mehrere Portale und zerstört Ruuk\'Jars Eier.','Das Gelege zerstören',69497),(16919,'esES','Entra en varios portales y destruye huevos de Ruuk\'Jar.','Destruye la nidada',69497),(16919,'esMX','Entra en varios portales y destruye los huevos de Ruuk\'Jar.','Destruye la nidada',69497),(16919,'frFR','Franchissez plusieurs portails et détruisez les œufs de Ruuk’Jar.','Détruire la couvée',69497),(16919,'itIT','Entra nei portali e distruggi le Uova di Ruuk\'jar.','Distruggi la Covata',69497),(16919,'koKR','여러 차원문에 들어가 루크자르의 알을 파괴해야 합니다.','알 무리 파괴',69497),(16919,'ptBR','Adentre vários portais e destrua os Ovos de Ruuk\'jar.','Destrua a ninhada',69497),(16919,'ruRU','Пройдите через порталы и уничтожьте кладку Руук\'джар.','Уничтожение кладки',69497),(16919,'zhCN','进入多个传送门并摧毁鲁克贾尔的卵。','摧毁孵化巢',69497),(16919,'zhTW','進入多個傳送門並摧毀魯克賈的蛋。','摧毀窩巢',69497),(17028,'deDE','Eine seltsame Truhe wurde entdeckt!','Truhe untersuchen',69497),(17028,'esES','¡Se ha descubierto un extraño alijo!','Examina el alijo',69497),(17028,'esMX','¡Has descubierto un alijo extraño!','Examina el alijo',69497),(17028,'frFR','Une étrange cache a été découverte !','Examiner la cache',69497),(17028,'itIT','È stata scoperta una strana cassa!','Esamina la Cassa',69497),(17028,'koKR','특이한 보관함이 발견됐습니다!','보관함 살펴보기',69497),(17028,'ptBR','Um baú estranho foi descoberto!','Examine o baú',69497),(17028,'ruRU','Обнаружен странный тайник!','Осмотр тайника',69497),(17028,'zhCN','发现了一个奇怪的宝箱！','检查宝箱',69497),(17028,'zhTW','發現了奇怪的儲物箱！','檢視儲物箱',69497),(17030,'deDE','Flammenschürer bereiten die Geisterscheiterhaufen vor.','Vorbereitung der Scheiterhaufen',69497),(17030,'esES','Los cuidallamas están preparando las piras espirituales.','Prepara las piras',69497),(17030,'esMX','Los cuidallamas están preparando las piras espirituales.','Prepara las piras',69497),(17030,'frFR','Les couve-flammes préparent les bûchers spirituels.','Préparation des bûchers',69497),(17030,'itIT','I Curafiamma stanno preparando le Pire Spirituali.','Preparare le Pire',69497),(17030,'koKR','불꽃지기가 영혼 장작더미를 준비하고 있습니다.','장작더미 준비',69497),(17030,'ptBR','Zelachamas estão preparando as Piras Espirituais.','Prepare as piras',69497),(17030,'ruRU','Мастера огня готовят призрачные погребальные костры.','Возжигание костров',69497),(17030,'zhCN','护火者正在准备精魂火堆。','准备火堆',69497),(17030,'zhTW','顧焰師正在準備靈魂火堆。','準備火堆',69497),(17032,'deDE','Macht Euch bereit, eine Flut von Schlangen baut sich auf.','Aus der Tiefe schlängeln',69497),(17032,'esES','Prepárate. Se alza una marea de sierpes.','Serpenteos de las profundidades',69497),(17032,'esMX','Prepárate: una oleada de serpientes se alza.','Repta desde las profundidades',69497),(17032,'frFR','Préparez-vous… une marée de serpents s’apprête à frapper.','Sifflements des profondeurs',69497),(17032,'itIT','Preparati, un\'ondata di serpenti si erge.','Serpeggiando dalle Profondità',69497),(17032,'koKR','뱀의 해일이 솟아오릅니다. 대비해야 합니다.','심연에서 기어 나오는 존재들',69497),(17032,'ptBR','Prepare-se: uma maré de serpentes avança.','Rastejando das Profundezas',69497),(17032,'ruRU','Готовьтесь, надвигается волна змей.','Пресмыкающиеся из глубин',69497),(17032,'zhCN','做好准备，蛇群狂潮正在涌现。','自深渊蜿蜒而来',69497),(17032,'zhTW','做好準備，蛇潮來了。','自深淵滑出',69497),(17044,'deDE','Betretet die Schattenseite und besiegt die Gegner dort.','Die Schattenseite räumen',69497),(17044,'esES','Entra en los Bajos Fondos y derrota a los enemigos que hay allí.','Limpia los Bajos Fondos',69497),(17044,'esMX','Entra en los Bajos Fondos y derrota a los enemigos.','Despeja los Bajos Fondos',69497),(17044